const plantPhotos=[["https://upload.wikimedia.org/wikipedia/commons/f/f5/Quercus_suber_leaves.jpg","https://commons.wikimedia.org/wiki/File:Quercus_suber_leaves.jpg","Madrone HeHeHe"],["https://upload.wikimedia.org/wikipedia/commons/b/b8/Nerium_oleander_flower_and_leaves.jpg","https://commons.wikimedia.org/wiki/File:Nerium_oleander_flower_and_leaves.jpg","Poojasasikumar"],["https://upload.wikimedia.org/wikipedia/commons/7/7b/Leaves_of_Acer_palmatum_%28Japanese_maple%29.jpg","https://commons.wikimedia.org/wiki/File:Leaves_of_Acer_palmatum_(Japanese_maple).jpg","Humoyun Mehridinov"],["https://upload.wikimedia.org/wikipedia/commons/5/5d/Olea_europaea_leaves.jpg","https://commons.wikimedia.org/wiki/File:Olea_europaea_leaves.jpg","Prahlad balaji"],["https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6e/Rose_Flower_%283%29.jpg/250px-Rose_Flower_%283%29.jpg","https://commons.wikimedia.org/wiki/File:Rose_Flower_(3).jpg","Sabina Bajracharya"],["https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/Tulipa_gesneriana2.jpg/330px-Tulipa_gesneriana2.jpg","https://commons.wikimedia.org/wiki/File:Tulipa_gesneriana2.jpg","Fizykaa"],["https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/Sunflower_in_Bloom_01.jpg/330px-Sunflower_in_Bloom_01.jpg","https://commons.wikimedia.org/wiki/File:Sunflower_in_Bloom_01.jpg","A S M Jobaer"],["https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c0/Bellis_perennis_%E2%80%93_Flower.jpg/250px-Bellis_perennis_%E2%80%93_Flower.jpg","https://commons.wikimedia.org/wiki/File:Bellis_perennis_%E2%80%93_Flower.jpg","August Geyler"],["https://thumb.wikimedia.org/wikipedia/commons/thumb/5/57/Phalaenopsis_flower.JPG/330px-Phalaenopsis_flower.JPG","https://commons.wikimedia.org/wiki/File:Phalaenopsis_flower.JPG","Remember"],["https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/Hibiscus_rosa-sinensis_flower_01.jpg/330px-Hibiscus_rosa-sinensis_flower_01.jpg","https://commons.wikimedia.org/wiki/File:Hibiscus_rosa-sinensis_flower_01.jpg","Syrio"]];
const plants=[
['Alcornoque','Quercus suber','a photo of a cork oak tree, Quercus suber, with small oval leathery green leaves','🌳'],
['Adelfa','Nerium oleander','a photo of an oleander plant, Nerium oleander, pink or white flowers and long narrow leaves','🌺'],
['Arce japonés','Acer palmatum','a photo of Japanese maple, Acer palmatum, with pointed lobed red or green leaves','🍁'],
['Olivo','Olea europaea','a photo of an olive tree, Olea europaea, narrow silvery leaves and olives','🫒'],
['Rosa','Rosa spp.','a photo of a rose flower with layers of overlapping petals','🌹'],
['Tulipán','Tulipa spp.','a photo of a tulip flower, an upright cup shaped flower','🌷'],
['Girasol','Helianthus annuus','a photo of a sunflower, yellow petals surrounding a large dark circular center','🌻'],
['Margarita','Bellis / Leucanthemum','a photo of a daisy flower, white petals surrounding a yellow center','🌼'],
['Orquídea','Orchidaceae','a photo of an orchid flower, a moth orchid with a distinctive central lip','🪷'],
['Hibisco','Hibiscus spp.','a photo of a hibiscus flower with five broad petals and a long protruding stamen','🌺']];
const $=s=>document.querySelector(s),MODEL='Xenova/clip-vit-base-patch32',KEY='flororda-photo-v1';
let state={samples:[],trained:null},selected=null,selectedVector=null,engine=null,loading=null,busy=false;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved?.model===MODEL&&Array.isArray(saved.samples)&&saved.samples.every(s=>Number.isInteger(s.label)&&s.label>=0&&s.label<10&&s.v?.length===512&&s.v.every(Number.isFinite))){state={samples:saved.samples,trained:saved.trained||null}}}catch{}
const norm=a=>{const n=Math.hypot(...a)||1;return Array.from(a,x=>x/n)},dot=(a,b)=>a.reduce((s,x,i)=>s+x*b[i],0);
function status(t){$('#photo-status').textContent=t}
function save(){try{localStorage.setItem(KEY,JSON.stringify({model:MODEL,...state}));return true}catch{status('No se pudo guardar: el navegador no tiene espacio. Exporta una copia antes de cerrar.');return false}}
function counts(){return plants.map((_,i)=>state.samples.filter(s=>s.label===i).length)}
function refresh(){const n=counts();$('#photo-classes').innerHTML=plants.map((p,i)=>`<div class="plant-chip"><a class="plant-photo-link" href="${plantPhotos[i][1]}" target="_blank" rel="noopener" title="Foto: ${plantPhotos[i][2]} · Fuente y licencia"><img src="${plantPhotos[i][0]}" alt="Fotografía real de ${p[0]}" loading="lazy" width="200" height="120"></a><div><b>${p[0]}</b><small>${p[1]}</small><small>${n[i]} foto${n[i]===1?'':'s'} propia${n[i]===1?'':'s'}</small></div></div>`).join('');$('#training-count').textContent=`${state.samples.length} fotos · ${n.filter(x=>x>0).length}/10 categorías con datos`;
$('#own-option').disabled=!state.trained;if(!state.trained)$('#photo-mode').value='base';$('#training-summary').textContent=state.trained?`Modelo propio listo: ${state.trained.centroids.length} categorías, ${state.trained.n} fotos. Validación por exclusión de una foto: ${(100*state.trained.cv).toFixed(1)} % (${state.trained.correct}/${state.trained.n}). Esta validación pequeña no sustituye una prueba con fotos nuevas.`:'Todavía no hay un modelo propio entrenado. Agrega al menos 3 fotos diferentes por categoría y 2 categorías. Para cubrir las 10, carga 30 fotos como mínimo.';}
function lock(v){busy=v;document.querySelectorAll('[data-ai-action]').forEach(b=>b.disabled=v);$('#photo-panel').setAttribute('aria-busy',String(v))}
function progress(p){if(p.status==='progress')status(`Descargando modelo visual: ${p.file.split('/').pop()} · ${Math.round(p.progress||0)} %`)}
async function init(){if(engine)return engine;if(loading)return loading;loading=(async()=>{status('Cargando motor visual. La primera vez descarga modelos grandes; mantén esta página abierta.');const T=await import('https://cdn.jsdelivr.net/npm/@huggingface/transformers@3.8.1');T.env.allowLocalModels=false;T.env.backends.onnx.wasm.numThreads=1;
const processor=await T.AutoProcessor.from_pretrained(MODEL);const vision=await T.CLIPVisionModelWithProjection.from_pretrained(MODEL,{dtype:'q8',device:'wasm',progress_callback:progress});status('Cargando comparador de categorías…');const tokenizer=await T.AutoTokenizer.from_pretrained(MODEL);const text=await T.CLIPTextModelWithProjection.from_pretrained(MODEL,{dtype:'q8',device:'wasm',progress_callback:progress});
const prompts=[...plants.map(p=>p[2]),'a photo of another plant or another flower not in this list','a photo of an object, person, animal, document or a landscape without a close up plant'];const tokens=tokenizer(prompts,{padding:true,truncation:true});const out=await text(tokens);const vectors=out.text_embeds.tolist().map(norm);out.text_embeds.dispose?.();for(const x of Object.values(tokens))x.dispose?.();await text.dispose();engine={T,processor,vision,vectors};status('Motor visual listo. Ya puedes identificar una foto o agregar ejemplos.');return engine})();try{return await loading}catch(e){loading=null;throw e}}
async function embedding(url){const e=await init();const image=await e.T.RawImage.read(url);const inputs=await e.processor(image);try{const output=await e.vision(inputs);const v=norm(output.image_embeds.data);output.image_embeds.dispose?.();return v}finally{for(const t of Object.values(inputs))t.dispose?.()}}
function fail(e){console.error(e);status('No se pudo completar: '+String(e.message||e));}
async function action(fn){if(busy)return;lock(true);try{await fn()}catch(e){fail(e)}finally{lock(false)}}
function centroid(samples){return norm(samples.reduce((a,s)=>a.map((v,i)=>v+s.v[i]),Array(512).fill(0)))}
function fit(samples){return plants.map((p,i)=>{const group=samples.filter(s=>s.label===i);return group.length?{label:i,v:centroid(group),n:group.length}:null}).filter(Boolean)}
function predict(v,centers){return centers.map(c=>({label:c.label,score:dot(v,c.v)})).sort((a,b)=>b.score-a.score)}
async function selectPhoto(file){if(!file)return;if(!file.type.startsWith('image/')||file.size>12*1024*1024)throw Error('Elige una imagen JPG, PNG o WebP de hasta 12 MB');if(selected?.owned)URL.revokeObjectURL(selected.url);selected={url:URL.createObjectURL(file),owned:true,file};selectedVector=null;$('#photo-preview').src=selected.url;$('#photo-preview').hidden=false;$('#photo-placeholder').hidden=true;$('#photo-result').textContent='Foto lista. Pulsa Identificar.';}
$('#photo-upload').addEventListener('change',()=>action(async()=>selectPhoto($('#photo-upload').files[0])));
$('#start-ai').addEventListener('click',()=>action(init));
$('#identify-photo').addEventListener('click',()=>action(async()=>{if(!selected)throw Error('Primero selecciona una foto');const e=await init();status('Analizando la imagen…');const v=selectedVector||(selectedVector=await embedding(selected.url));let results,unknown=false;
if($('#photo-mode').value==='own'){if(!state.trained)throw Error('Primero entrena tu modelo');results=predict(v,state.trained.centroids);unknown=results[0].score<.65||results[0].score-results[1].score<.025;}else{results=e.vectors.map((p,i)=>({label:i,score:dot(v,p)})).sort((a,b)=>b.score-a.score);unknown=results[0].label>=10||results[0].score<.20||results[0].score-results[1].score<.015;}
const top=results.filter(x=>x.label<10).slice(0,3),name=plants[top[0].label];$('#photo-result').innerHTML=`<p class="eyebrow">${$('#photo-mode').value==='own'?'MODELO ENTRENADO CON TUS FOTOS':'MODELO VISUAL PREENTRENADO · SIN ENTRENAMIENTO LOCAL'}</p><h3>${unknown?'Resultado no concluyente':name[0]}</h3><p>${unknown?'La imagen no permite distinguir con claridad una categoría. Prueba una foto cercana, con buena luz y una sola planta.':'Coincidencia visual más cercana: <i>'+name[1]+'</i>.'}</p><div>${top.map(r=>`<div class="match-row"><span>${plants[r.label][0]}</span><span>Similitud ${(100*r.score).toFixed(1)}/100</span></div><div class="track"><div class="fill" style="width:${Math.max(0,r.score*100)}%"></div></div>`).join('')}</div><small>Las similitudes no son probabilidades ni una exactitud medida. ${$('#photo-mode').value==='own'?'Solo compara las categorías que has entrenado.':'Compara estas 10 categorías y dos alternativas generales.'} Puede equivocarse.</small>`;status('Análisis terminado. Puedes probar otra imagen.');}));
$('#train-label').innerHTML=plants.map((p,i)=>`<option value="${i}">${p[0]} · ${p[1]}</option>`).join('');
$('#add-training').addEventListener('click',()=>action(async()=>{const files=Array.from($('#train-upload').files),label=+$('#train-label').value;if(!files.length)throw Error('Selecciona fotos para la categoría elegida');if(counts()[label]+files.length>40)throw Error('Usa como máximo 40 fotos por categoría');await init();let added=0,duplicate=0,failed=0;for(let i=0;i<files.length;i++){const f=files[i];if(!f.type.startsWith('image/')||f.size>12*1024*1024){failed++;continue}status(`Procesando foto ${i+1}/${files.length} de ${plants[label][0]}…`);let url;try{const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await f.arrayBuffer()))).map(x=>x.toString(16).padStart(2,'0')).join('');if(state.samples.some(s=>s.hash===hash)){duplicate++;continue}url=URL.createObjectURL(f);const v=await embedding(url);state.samples.push({label,v,hash});added++;}catch(e){failed++;console.error(e)}finally{if(url)URL.revokeObjectURL(url)}}if(added){state.trained=null;save();refresh()}$('#train-upload').value='';status(`${added} fotos añadidas; ${duplicate} duplicadas omitidas; ${failed} no procesadas. Pulsa Entrenar cuando tengas suficientes fotos.`);}));
$('#train-photo-model').addEventListener('click',()=>action(async()=>{const n=counts(),active=n.filter(x=>x>0);if(active.length<2||active.some(x=>x<3))throw Error('Necesitas 2 categorías como mínimo y 3 fotos distintas en cada categoría activa');status('Entrenando clasificador y validando sin reutilizar la foto evaluada…');await new Promise(r=>setTimeout(r,40));let correct=0;for(let i=0;i<state.samples.length;i++){const held=state.samples[i];const centers=fit(state.samples.filter((_,j)=>j!==i));if(predict(held.v,centers)[0].label===held.label)correct++;}state.trained={centroids:fit(state.samples),n:state.samples.length,correct,cv:correct/state.samples.length,created:new Date().toISOString()};save();refresh();$('#photo-mode').value='own';status('Entrenamiento terminado. El modo «Mi modelo» está activo. Evalúalo ahora con fotos nuevas que no hayas usado para entrenar.');}));
$('#export-photo-model').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({format:'flororda-photo-v1',model:MODEL,plants:plants.map(p=>p[0]),...state})],{type:'application/json'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='FlorOrda_Entrenamiento_Fotos.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)});
$('#reset-photo-model').addEventListener('click',()=>{if(busy)return;if(!confirm('¿Borrar las fotos procesadas y el modelo guardados en este navegador? Puedes exportar una copia antes.'))return;state={samples:[],trained:null};localStorage.removeItem(KEY);refresh();status('Modelo local eliminado. El reconocimiento preentrenado sigue disponible.');});
$('#import-photo-model').addEventListener('change',()=>action(async()=>{const f=$('#import-photo-model').files[0];if(!f)return;if(f.size>8*1024*1024)throw Error('Archivo demasiado grande');const obj=JSON.parse(await f.text());if(obj.format!=='flororda-photo-v1'||obj.model!==MODEL||!Array.isArray(obj.samples)||obj.samples.length>400||!obj.samples.every(s=>Number.isInteger(s.label)&&s.label>=0&&s.label<10&&s.v?.length===512&&s.v.every(Number.isFinite)&&typeof s.hash==='string'))throw Error('El archivo no es un entrenamiento compatible');state={samples:obj.samples,trained:null};save();refresh();status('Datos de entrenamiento importados. Pulsa Entrenar para reconstruir tu modelo.');}));
// Ejemplos reales procedentes de las fichas actuales, sin transmitir fotos del usuario.
document.querySelectorAll('[data-photo-example]').forEach(b=>b.addEventListener('click',()=>action(async()=>{if(selected?.owned)URL.revokeObjectURL(selected.url);selected={url:b.dataset.photoExample,owned:false};selectedVector=null;$('#photo-preview').src=selected.url;$('#photo-preview').hidden=false;$('#photo-placeholder').hidden=true;$('#photo-result').textContent='Ejemplo real cargado. Pulsa Identificar para obtener una predicción real del modelo.';})));
refresh();
